static void Adjust(std::string* f, int hole, int len, std::string val)
{
    int top = hole, child = 2 * hole + 2;
    while (child < len) { if (f[child] < f[child - 1]) --child; f[hole] = f[child]; hole = child; child = 2 * child + 2; }
